package com.agrolink.controller;import com.agrolink.dto.order.*;import com.agrolink.dto.product.*;import com.agrolink.dto.review.*;import com.agrolink.dto.user.*;import com.agrolink.service.AdminService;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasRole('ADMIN')") public class AdminController{private final AdminService s;public AdminController(AdminService s){this.s=s;}@GetMapping("/orders")public List<OrderResponse> orders(){return s.orders();}@PutMapping("/orders/{id}")public OrderResponse order(@PathVariable Long id,@RequestParam String status){return s.updateOrder(id,status);}@GetMapping("/reviews")public List<ReviewResponse> reviews(){return s.reviews();}@PutMapping("/reviews/{id}")public ReviewResponse review(@PathVariable Long id,@RequestParam String status){return s.moderateReview(id,status);}@GetMapping("/users")public List<UserResponse> users(){return s.users();}@PutMapping("/users/{id}")public UserResponse user(@PathVariable Long id,@RequestParam boolean enabled){return s.setUserEnabled(id,enabled);}@GetMapping("/products")public List<ProductResponse> products(){return s.products();}@PutMapping("/products/{id}")public ProductResponse product(@PathVariable Long id,@RequestParam String status){return s.setProductStatus(id,status);}@GetMapping("/stats")public Map<String,Long> stats(){return s.stats();}}